/**
 * @fileoverview Flutter Compiler (Bridge target)
 * @module @holoscript/core/compiler
 *
 * PURPOSE:
 * Compile HoloScript compositions to Flutter/Dart widget code.
 * Emits a single Dart source file containing a StatelessWidget (or
 * StatefulWidget when @stateful trait is present), wrapped in a
 * MaterialApp scaffold when a root scene is present.
 *
 * // Generated by HoloScript FlutterCompiler
 */

import type {
  HoloComposition,
  HoloObjectDecl,
  HoloObjectTrait,
  HoloSpatialGroup,
  HoloTheme,
  HoloValue,
} from '../parser/HoloCompositionTypes.js';
import { CompilerBase, type CompilerToken } from './CompilerBase';
import { ANSCapabilityPath, type ANSCapabilityPathValue } from '@holoscript/core-types/ans';

// ---------------------------------------------------------------------------
// Public option types
// ---------------------------------------------------------------------------

export interface FlutterCompilerOptions {
  /** Dart package name used in the generated file header */
  packageName: string;
  /** Whether to emit debug labels for unrecognised node types */
  emitDebugPlaceholders: boolean;
}

// ---------------------------------------------------------------------------
// Result type
// ---------------------------------------------------------------------------

export interface FlutterCompilationResult {
  success: boolean;
  /** Dart source code ready to write to a .dart file */
  code: string;
  warnings: string[];
  errors: string[];
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/** Dart identifier from an arbitrary string — strips non-word chars. */
function toDartIdentifier(value: string): string {
  const safe = value.replace(/[^A-Za-z0-9_]/g, '_').replace(/^[^A-Za-z_]+/, '');
  return safe || 'widget';
}

/** PascalCase conversion for class names. */
function toPascalCase(value: string): string {
  return value
    .replace(/[^A-Za-z0-9]+(.)/g, (_, ch: string) => ch.toUpperCase())
    .replace(/^(.)/, (ch: string) => ch.toUpperCase());
}

/** Dart string literal with escaping. */
function dartString(value: string): string {
  const escaped = value
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t')
    .replace(/\0/g, '\\x00');
  return `'${escaped}'`;
}

// ---------------------------------------------------------------------------
// FlutterCompiler
// ---------------------------------------------------------------------------

export class FlutterCompiler extends CompilerBase {
  protected readonly compilerName = 'FlutterCompiler';

  protected override getRequiredCapability(): ANSCapabilityPathValue {
    // Flutter targets the mobile compilation domain
    return ANSCapabilityPath.ANDROID;
  }

  private options: FlutterCompilerOptions;
  private errors: string[] = [];
  private warnings: string[] = [];
  private lines: string[] = [];
  private indentLevel = 0;

  constructor(options: Partial<FlutterCompilerOptions> = {}) {
    super();
    this.options = {
      packageName: options.packageName ?? 'com.holoscript.generated',
      emitDebugPlaceholders: options.emitDebugPlaceholders ?? true,
    };
  }

  // =========================================================================
  // Public API
  // =========================================================================

  override compile(
    composition: HoloComposition,
    agentToken: string,
    outputPath?: string
  ): FlutterCompilationResult {
    this.validateCompilerAccess(agentToken as CompilerToken, outputPath);
    this.errors = [];
    this.warnings = [];
    this.lines = [];
    this.indentLevel = 0;

    if (!composition || composition.type !== 'Composition') {
      this.errors.push('Invalid composition tree');
      return this.buildResult();
    }

    const compositionName = composition.name || 'GeneratedScene';
    const isStateful = this.compositionHasTrait(composition, 'stateful');
    const hasRootScene = (composition.scenes?.length ?? 0) > 0;

    this.emitFileHeader(compositionName);
    this.emitImports();
    this.emitBlankLine();
    this.emitColorScheme(composition.theme);
    this.emitBlankLine();
    this.emitWidgetClass(composition, compositionName, isStateful, hasRootScene);

    return this.buildResult();
  }

  // =========================================================================
  // File-level emitters
  // =========================================================================

  private emitFileHeader(compositionName: string): void {
    this.emit(`// Generated by HoloScript FlutterCompiler`);
    this.emit(`// Composition: ${compositionName}`);
    this.emit(`// Package: ${this.options.packageName}`);
    this.emitBlankLine();
  }

  private emitImports(): void {
    this.emit(`import 'package:flutter/material.dart';`);
  }

  private emitColorScheme(theme?: HoloTheme): void {
    if (!theme) return;

    const colorEntries: string[] = [];
    for (const prop of theme.properties) {
      if (prop.key === 'color' || prop.key === 'primaryColor' || prop.key === 'primary') {
        colorEntries.push(`  primary: ${this.dartColor(String(prop.value), 'blue')},`);
      } else if (prop.key === 'backgroundColor' || prop.key === 'background') {
        colorEntries.push(`  background: ${this.dartColor(String(prop.value), 'white')},`);
      } else if (prop.key === 'secondaryColor' || prop.key === 'secondary') {
        colorEntries.push(`  secondary: ${this.dartColor(String(prop.value), 'grey')},`);
      }
    }

    if (colorEntries.length === 0) return;

    this.emit(`// Theme color scheme derived from HoloScript @color traits`);
    this.emit(`final _colorScheme = ColorScheme.fromSeed(`);
    this.emit(`  seedColor: Colors.blue,`);
    for (const entry of colorEntries) {
      this.emit(entry);
    }
    this.emit(`);`);
  }

  // =========================================================================
  // Widget class emitter
  // =========================================================================

  private emitWidgetClass(
    composition: HoloComposition,
    compositionName: string,
    isStateful: boolean,
    hasRootScene: boolean
  ): void {
    const className = `${toPascalCase(compositionName)}Widget`;
    const baseClass = isStateful ? 'StatefulWidget' : 'StatelessWidget';

    this.emit(`class ${className} extends ${baseClass} {`);
    this.indent();
    this.emit(`const ${className}({super.key});`);
    this.emitBlankLine();

    if (isStateful) {
      this.emit(`@override`);
      this.emit(`State<${className}> createState() => _${className}State();`);
      this.dedent();
      this.emit(`}`);
      this.emitBlankLine();
      this.emit(`class _${className}State extends State<${className}> {`);
      this.indent();
    }

    this.emit(`@override`);
    this.emit(`Widget build(BuildContext context) {`);
    this.indent();

    const body = this.buildBody(composition, hasRootScene);
    this.emit(`return ${body};`);

    this.dedent();
    this.emit(`}`);
    this.dedent();
    this.emit(`}`);
  }

  // =========================================================================
  // Body builder — MaterialApp scaffold or bare widget
  // =========================================================================

  private buildBody(composition: HoloComposition, hasRootScene: boolean): string {
    const innerWidget = this.buildInnerWidget(composition);

    if (!hasRootScene) {
      return innerWidget;
    }

    const sceneName = composition.scenes?.[0]?.name ?? 'Home';
    const themeArg = composition.theme ? `\n      theme: ThemeData(colorScheme: _colorScheme),` : '';

    return (
      `MaterialApp(\n` +
      `      title: ${dartString(composition.name || sceneName)},` +
      themeArg +
      `\n      home: Scaffold(\n` +
      `        appBar: AppBar(title: const Text(${dartString(sceneName)})),\n` +
      `        body: ${innerWidget},\n` +
      `      ),\n` +
      `    )`
    );
  }

  private buildInnerWidget(composition: HoloComposition): string {
    const parts: string[] = [];

    // Top-level objects
    for (const obj of composition.objects) {
      parts.push(this.compileObject(obj));
    }

    // Top-level spatial groups
    for (const group of composition.spatialGroups) {
      parts.push(this.compileSpatialGroup(group));
    }

    if (parts.length === 0) {
      return `const SizedBox.shrink()`;
    }

    if (parts.length === 1) {
      return parts[0]!;
    }

    return `Column(\n      children: [\n${parts.map((p) => `        ${p},`).join('\n')}\n      ],\n    )`;
  }

  // =========================================================================
  // Object compiler — maps HoloScript object types to Flutter widgets
  // =========================================================================

  private compileObject(node: HoloObjectDecl): string {
    const objType = this.getPropString(node, 'type') || node.name.toLowerCase();
    const width = this.getPropNumber(node, 'width');
    const height = this.getPropNumber(node, 'height');
    const padding = this.getPropNumber(node, 'padding');

    let widget = this.compileObjectByType(node, objType, width, height);

    // Wrap with SizedBox if explicit width/height but not already a Container
    if ((width !== undefined || height !== undefined) && !widget.startsWith('Container')) {
      const w = width !== undefined ? `width: ${width},` : '';
      const h = height !== undefined ? `height: ${height},` : '';
      widget = `SizedBox(${w}${h} child: ${widget})`;
    }

    // Wrap with Padding if @padding trait present
    if (padding !== undefined) {
      widget = `Padding(\n  padding: EdgeInsets.all(${padding}),\n  child: ${widget},\n)`;
    }

    return widget;
  }

  private compileObjectByType(
    node: HoloObjectDecl,
    objType: string,
    width: number | undefined,
    height: number | undefined
  ): string {
    switch (objType) {
      case 'box':
      case 'cube':
        return this.compileBox(node, width, height);

      case 'text':
        return this.compileText(node);

      case 'image':
        return this.compileImage(node);

      case 'button':
        return this.compileButton(node);

      case 'sphere':
      case 'circle':
        return this.compileCircle(node, width, height);

      case 'video':
        return this.compileVideo(node);

      default:
        return this.compileDefault(node, objType);
    }
  }

  // ──────────────────────────────────────────────────────────────────────────
  // Widget generators

  private compileBox(node: HoloObjectDecl, width?: number, height?: number): string {
    const color = this.getPropString(node, 'color');
    const colorArg = color ? `color: ${this.dartColor(color, 'blue')},` : '';
    const widthArg = width !== undefined ? `width: ${width},` : '';
    const heightArg = height !== undefined ? `height: ${height},` : '';
    return `Container(${widthArg}${heightArg}${colorArg})`;
  }

  private compileText(node: HoloObjectDecl): string {
    const content = this.getPropString(node, 'text') ||
      this.getPropString(node, 'content') ||
      this.getPropString(node, 'label') ||
      node.name;
    const fontSize = this.getPropNumber(node, 'fontSize') ?? this.getPropNumber(node, 'font_size');
    const color = this.getPropString(node, 'color');

    const styleArgs: string[] = [];
    if (fontSize !== undefined) styleArgs.push(`fontSize: ${fontSize}`);
    if (color) styleArgs.push(`color: ${this.dartColor(color, 'black')}`);

    const styleArg =
      styleArgs.length > 0 ? `, style: const TextStyle(${styleArgs.join(', ')})` : '';

    return `Text(${dartString(content)}${styleArg})`;
  }

  private compileImage(node: HoloObjectDecl): string {
    const src = this.getTraitValue(node, 'src', ['src', 'url', 'source']);
    if (src !== undefined) {
      return `Image.network(${dartString(String(src))})`;
    }
    const asset = this.getPropString(node, 'asset') || this.getPropString(node, 'src');
    if (asset) {
      return `Image.asset(${dartString(asset)})`;
    }
    return `Image.network(${dartString('')})`;
  }

  private compileButton(node: HoloObjectDecl): string {
    const label = this.getPropString(node, 'label') ||
      this.getPropString(node, 'text') ||
      node.name;
    return (
      `ElevatedButton(\n` +
      `  onPressed: () {},\n` +
      `  child: Text(${dartString(label)}),\n` +
      `)`
    );
  }

  private compileCircle(node: HoloObjectDecl, width?: number, height?: number): string {
    const color = this.getPropString(node, 'color');
    const size = width ?? height ?? 48;
    const colorArg = color
      ? `color: ${this.dartColor(color, 'blue')},`
      : `color: Colors.blue,`;
    return (
      `Container(\n` +
      `  width: ${size},\n` +
      `  height: ${size},\n` +
      `  decoration: BoxDecoration(shape: BoxShape.circle, ${colorArg}),\n` +
      `)`
    );
  }

  private compileVideo(_node: HoloObjectDecl): string {
    return (
      `Placeholder(\n` +
      `  // TODO: video_player package\n` +
      `  fallbackHeight: 200,\n` +
      `)`
    );
  }

  private compileDefault(node: HoloObjectDecl, objType: string): string {
    if (!this.options.emitDebugPlaceholders) {
      return `const SizedBox.shrink()`;
    }
    return (
      `Placeholder(\n` +
      `  // Unrecognised HoloScript type: ${objType} (${node.name})\n` +
      `  fallbackHeight: 50,\n` +
      `)`
    );
  }

  // =========================================================================
  // Spatial group compiler — Row / Column / Stack
  // =========================================================================

  private compileSpatialGroup(group: HoloSpatialGroup): string {
    const layoutProp = group.properties.find((p) => p.key === 'layout');
    const layout = typeof layoutProp?.value === 'string' ? layoutProp.value : 'column';

    const children = group.objects.map((obj) => `  ${this.compileObject(obj)},`).join('\n');
    const childArray = `[\n${children}\n]`;

    // Nested groups
    const nestedGroups = (group.groups ?? [])
      .map((g) => `  ${this.compileSpatialGroup(g)},`)
      .join('\n');

    const allChildren = [children, nestedGroups].filter(Boolean).join('\n');
    const fullChildArray = `[\n${allChildren}\n]`;

    switch (layout) {
      case 'row':
        return `Row(children: ${fullChildArray})`;
      case 'stack':
        return `Stack(children: ${fullChildArray})`;
      case 'column':
      default:
        return `Column(children: ${fullChildArray})`;
    }
  }

  // =========================================================================
  // AST helpers
  // =========================================================================

  private compositionHasTrait(composition: HoloComposition, traitName: string): boolean {
    return (composition.traits ?? []).some(
      (t) => String(t.name).replace(/^@/, '') === traitName
    );
  }

  private getTrait(node: HoloObjectDecl, traitName: string): HoloObjectTrait | undefined {
    const clean = traitName.startsWith('@') ? traitName.slice(1) : traitName;
    return node.traits.find((t) => String(t.name).replace(/^@/, '') === clean);
  }

  private getTraitValue(
    node: HoloObjectDecl,
    traitName: string,
    keys: string[]
  ): HoloValue | undefined {
    const trait = this.getTrait(node, traitName);
    const cfg = trait?.config ?? trait?.params ?? {};
    for (const key of keys) {
      if (cfg[key] !== undefined) return cfg[key];
    }
    return undefined;
  }

  private getPropString(node: HoloObjectDecl, key: string): string | undefined {
    const prop = node.properties.find((p) => p.key === key);
    if (prop === undefined) return undefined;
    if (typeof prop.value === 'string') return prop.value;
    if (typeof prop.value === 'number' || typeof prop.value === 'boolean') {
      return String(prop.value);
    }
    return undefined;
  }

  private getPropNumber(node: HoloObjectDecl, key: string): number | undefined {
    const prop = node.properties.find((p) => p.key === key);
    if (prop === undefined) return undefined;
    if (typeof prop.value === 'number' && Number.isFinite(prop.value)) return prop.value;
    if (typeof prop.value === 'string') {
      const n = Number(prop.value);
      if (Number.isFinite(n)) return n;
    }
    return undefined;
  }

  // =========================================================================
  // Color mapping
  // =========================================================================

  /**
   * Maps a CSS-like color string to a Dart Color expression.
   * Supports: named colors (blue, red, green, white, black, grey/gray,
   * orange, purple, yellow, pink, teal, cyan, amber, indigo, lime),
   * hex shorthand (#RGB), and full hex (#RRGGBB / #AARRGGBB).
   */
  private dartColor(colorValue: string, fallback: string): string {
    const v = colorValue.trim().toLowerCase();

    const namedColors: Record<string, string> = {
      blue: 'Colors.blue',
      red: 'Colors.red',
      green: 'Colors.green',
      white: 'Colors.white',
      black: 'Colors.black',
      grey: 'Colors.grey',
      gray: 'Colors.grey',
      orange: 'Colors.orange',
      purple: 'Colors.purple',
      yellow: 'Colors.yellow',
      pink: 'Colors.pink',
      teal: 'Colors.teal',
      cyan: 'Colors.cyan',
      amber: 'Colors.amber',
      indigo: 'Colors.indigo',
      lime: 'Colors.lime',
      transparent: 'Colors.transparent',
    };

    if (namedColors[v]) return namedColors[v]!;

    // Hex colour
    if (v.startsWith('#')) {
      const hex = v.slice(1);
      if (hex.length === 3) {
        // #RGB → #AARRGGBB
        const r = hex[0]!.repeat(2);
        const g = hex[1]!.repeat(2);
        const b = hex[2]!.repeat(2);
        return `const Color(0xFF${r}${g}${b})`;
      }
      if (hex.length === 6) {
        return `const Color(0xFF${hex.toUpperCase()})`;
      }
      if (hex.length === 8) {
        return `const Color(0x${hex.toUpperCase()})`;
      }
    }

    // Unrecognised — fall back
    this.warnings.push(`Unrecognised color value '${colorValue}', using fallback`);
    return namedColors[fallback] ?? 'Colors.blue';
  }

  // =========================================================================
  // Line emitters
  // =========================================================================

  private emit(line: string): void {
    const prefix = '  '.repeat(this.indentLevel);
    this.lines.push(`${prefix}${line}`);
  }

  private emitBlankLine(): void {
    this.lines.push('');
  }

  private indent(): void {
    this.indentLevel++;
  }

  private dedent(): void {
    if (this.indentLevel > 0) this.indentLevel--;
  }

  // =========================================================================
  // Result assembly
  // =========================================================================

  private buildResult(): FlutterCompilationResult {
    return {
      success: this.errors.length === 0,
      code: this.lines.join('\n'),
      warnings: this.warnings,
      errors: this.errors,
    };
  }
}

export default FlutterCompiler;
